-- Stock trades members of Congress disclose under the STOCK Act (periodic
-- transaction reports: the House Clerk's PDFs and the Senate's eFD site), shown
-- on a person's page and watched from it. One row per transaction line. A
-- disclosure gives an amount as a range, never an exact figure, so the range is
-- kept as low/high. Nothing here is estimated: what a filing does not say stays
-- NULL (a missing ticker, a missing owner).
CREATE TABLE "PersonTrade" (
  "id"             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "personId"       integer NOT NULL REFERENCES "Person" ("id") ON DELETE CASCADE,
  -- 'house' or 'senate'; the filing's id in that chamber's system (the House
  -- Clerk's DocID, the Senate's report uuid). One filing carries many trades
  -- and is what a subscriber is told about.
  "chamber"        varchar(6) NOT NULL CHECK ("chamber" IN ('house', 'senate')),
  "filingId"       varchar(40) NOT NULL,
  -- Who holds the asset: 'self', 'spouse', 'joint' or 'dependent'.
  "owner"          varchar(10) NOT NULL DEFAULT 'self' CHECK ("owner" IN ('self', 'spouse', 'joint', 'dependent')),
  "asset"          varchar(300) NOT NULL,
  "ticker"         varchar(16),
  -- The filing's own code: ST stock, OP option, CS corporate bond, GS
  -- government security, OT other, and so on.
  "assetType"      varchar(8),
  "txType"         varchar(10) NOT NULL CHECK ("txType" IN ('purchase', 'sale', 'partial', 'exchange')),
  "txDate"         date NOT NULL,
  -- When the member notified the House or Senate, and when the filing was made.
  "notifiedDate"   date,
  "filedDate"      date,
  "amountLow"      bigint,
  "amountHigh"     bigint,
  "sourceUrl"      text NOT NULL,
  "utcCreatedDateTime" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "UC_PersonTrade_line" UNIQUE ("personId", "chamber", "filingId", "owner", "asset", "txType", "txDate", "amountLow")
);
CREATE INDEX "IX_PersonTrade_personId" ON "PersonTrade" ("personId", "txDate" DESC);
CREATE INDEX "IX_PersonTrade_ticker" ON "PersonTrade" ("ticker") WHERE "ticker" IS NOT NULL;

-- Who is told when a person files new trades. Soft delete + revive, as Follow.
CREATE TABLE "PersonTradeWatch" (
  "userId"             integer NOT NULL REFERENCES "User" ("id") ON DELETE CASCADE,
  "personId"           integer NOT NULL REFERENCES "Person" ("id") ON DELETE CASCADE,
  "utcCreatedDateTime" timestamptz NOT NULL DEFAULT now(),
  "utcDeletedDateTime" timestamptz,
  PRIMARY KEY ("userId", "personId")
);
CREATE INDEX "IX_PersonTradeWatch_personId" ON "PersonTradeWatch" ("personId") WHERE "utcDeletedDateTime" IS NULL;

-- A 'trade' notification is about a person's filing: one per watcher and filing.
ALTER TABLE "Notification" ADD COLUMN "personId" integer, ADD COLUMN "tradeFiling" varchar(40);
CREATE UNIQUE INDEX "UX_Notification_trade" ON "Notification" ("userId", "personId", "tradeFiling") WHERE "type" = 'trade';
